mapper.select:
select i.item_code as itemCode, i.item_name as itemName, coalesce(nullif(i.item_type_name, ''), '自制产品') as productType, i.specification, coalesce(nullif(i.unit_name, ''), i.unit_of_measure) as unit, case i.enable_flag when 'Y' then '已启用' else '已停用' end as status, count(*) over () as matchedCount from md_item i where i.item_or_product = 'PRODUCT'
and (locate(#{query}, i.item_code) > 0 or locate(#{query}, i.item_name) > 0 or locate(#{query}, i.item_type_name) > 0)
order by i.item_type_id, i.item_code limit #{limit}

mapper.sql:
where t.transaction_date >= #{from}
  and t.transaction_date < date_add(#{to}, interval 1 day)
  and (t.transaction_type = 'ITEM_RECPT' or t.source_doc_type = 'ITEM_RECPT')
  and t.transaction_quantity > 0
and t.item_code = #{itemCode}

mapper.select:
select t.item_code as itemCode, t.item_name as itemName, t.source_doc_code as receiptCode, date_format(t.transaction_date, '%Y-%m-%d %H:%i:%s') as receivedAt, t.transaction_quantity as quantity, coalesce(t.unit_name, t.unit_of_measure) as unit, t.warehouse_name as warehouseName , r.vendor_name as vendorName from wm_transaction t
left join wm_item_recpt r on r.recpt_id = t.source_doc_id and r.recpt_code = t.source_doc_code
order by t.transaction_date desc, t.transaction_id desc limit #{limit} offset #{offset}

select item_code as itemCode, item_name as itemName, unit_name as unit,
       current_stock as balance, min_stock as minStock, abs(gap) as shortage,
       case alert_level when 'CRITICAL' then '缺货' else '低于安全库存' end as alert,
       count(*) over () as matchedCount
from v_stock_alert where alert_level in ('CRITICAL', 'WARNING')

order by case alert_level when 'CRITICAL' then 0 else 1 end, gap, item_code limit #{limit}

select item_code as itemCode, item_name as itemName, specification, coalesce(unit_name, unit_of_measure) as unit, item_type_name as category, case enable_flag when 'Y' then '已启用' else '已停用' end as status, count(*) over () as matchedCount from md_item where
(locate(#{token}, item_code) > 0 or locate(#{token}, item_name) > 0)
order by item_code limit #{limit}


where b.bom_id in
  #{bomId}
order by b.bom_id
